#!/usr/bin/env node
/**
 * Diagnostic script to check build configuration
 */

import { existsSync } from 'fs'
import { resolve } from 'path'
import { createRequire } from 'module'

const projectRoot = process.cwd()
const require = createRequire(import.meta.url)

console.log('🔍 ULS Build Diagnostic\n')
console.log(`Project root: ${projectRoot}\n`)

// Check 1: vite.config.build.mjs
const viteConfigPath = resolve(projectRoot, 'vite.config.build.mjs')
console.log(`1. Build config: ${viteConfigPath}`)
if (existsSync(viteConfigPath)) {
  console.log('   ✅ Found')
  try {
    const config = await import(viteConfigPath + '?update=' + Date.now())
    console.log('   ✅ Valid ES module')
  } catch (err) {
    console.log(`   ❌ Error loading: ${err.message}`)
  }
} else {
  console.log('   ❌ Not found - Run: npx uls-init')
}

// Check 2: uls.config.cjs
const ulsConfigPath = resolve(projectRoot, 'uls.config.cjs')
console.log(`\n2. ULS config: ${ulsConfigPath}`)
if (existsSync(ulsConfigPath)) {
  console.log('   ✅ Found')
  try {
    const ulsConfig = require(ulsConfigPath)
    console.log(`   ✅ Valid config`)
    console.log(`   Styles path: ${ulsConfig.stylesPath || 'not set'}`)
    if (ulsConfig.purge) {
      console.log(`   Purge HTML files: ${ulsConfig.purge.htmlFiles?.join(', ') || 'not set'}`)
    }
  } catch (err) {
    console.log(`   ❌ Error loading: ${err.message}`)
  }
} else {
  console.log('   ⚠️  Not found - Will use defaults')
}

// Check 3: Entry LESS file
let stylesPath = 'src/styles/uls'
try {
  if (existsSync(ulsConfigPath)) {
    const ulsConfig = require(ulsConfigPath)
    stylesPath = ulsConfig.stylesPath || stylesPath
  }
} catch (e) {
  // Use default
}

const lessEntry = resolve(projectRoot, stylesPath, 'uls-master.less')
const lessEntryOnly = resolve(projectRoot, stylesPath, 'uls.less')

console.log(`\n3. LESS entry files:`)
console.log(`   Master: ${lessEntry}`)
if (existsSync(lessEntry)) {
  console.log('   ✅ Found')
} else {
  console.log('   ❌ Not found')
  console.log(`   Expected: ${lessEntry}`)
}

console.log(`   Core only: ${lessEntryOnly}`)
if (existsSync(lessEntryOnly)) {
  console.log('   ✅ Found')
} else {
  console.log('   ⚠️  Not found (optional)')
}

// Check 4: Dependencies
console.log(`\n4. Dependencies:`)
const packageJsonPath = resolve(projectRoot, 'package.json')
if (existsSync(packageJsonPath)) {
  try {
    const pkg = require(packageJsonPath)
    const deps = { ...pkg.dependencies, ...pkg.devDependencies }
    
    const required = ['less', 'vite', '@fullhuman/postcss-purgecss', 'postcss']
    for (const dep of required) {
      if (deps[dep]) {
        console.log(`   ✅ ${dep}: ${deps[dep]}`)
      } else {
        console.log(`   ❌ ${dep}: Missing`)
      }
    }
  } catch (err) {
    console.log(`   ❌ Error reading package.json: ${err.message}`)
  }
} else {
  console.log('   ❌ package.json not found')
}

// Check 5: Output directory
const outputDir = resolve(projectRoot, 'dist/css')
console.log(`\n5. Output directory: ${outputDir}`)
if (existsSync(outputDir)) {
  console.log('   ✅ Exists')
} else {
  console.log('   ⚠️  Will be created on build')
}

console.log('\n✅ Diagnostic complete')
console.log('\nIf entry file is missing, run: npx uls-init')
console.log('If dependencies are missing, run: npm install')

